from math import *
def pi_euler(x):
    s2=1
    i=2
    while True:
        s1=s2
        s2=s1+(1/(i*i))
        i=i+1
        if(abs(sqrt(s1*6)-sqrt(s2*6))<=x):
            break
    return sqrt(s2*6)
print("La valeur approché de pi euler à 10^4 prés est: ",pi_euler(0.0001))

